{"file_path":"src/parse.js","content":"import { CliError } from './errors.js'

const NAME_RE = /^[A-Za-z0-9_.-]+$/
const COST_RE = /^[0-9]+$/

/**
 * Parses the build graph text format described in the task prompt into a
 * map of task name to `{ name, cost, deps }`, where `deps` is a Set of
 * task names.
 */
export function parseGraph(input) {
  const rawLines = input.split('\n')
  if (rawLines.length > 0 && rawLines[rawLines.length - 1] === '') {
    rawLines.pop()
  }

  const tasks = new Map()
  const pendingDeps = []
  const usageOrder = []

  for (let i = 0; i < rawLines.length; i++) {
    const lineNumber = i + 1
    const trimmed = rawLines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const words = trimmed.split(/\s+/)
    const directive = words[0]

    if (directive === 'task') {
      if (words.length !== 3) {
        throw new CliError(`line ${lineNumber}: expected task <name> <cost>`, 2)
      }
      const [, name, costStr] = words
      if (!NAME_RE.test(name)) {
        throw new CliError(`line ${lineNumber}: invalid task name ${name}`, 2)
      }
      if (!COST_RE.test(costStr)) {
        throw new CliError(`line ${lineNumber}: cost must be a non-negative integer`, 2)
      }
      if (tasks.has(name)) {
        throw new CliError(`line ${lineNumber}: task ${name} is declared twice`, 2)
      }
      tasks.set(name, { name, cost: parseInt(costStr, 10), deps: new Set() })
    } else if (directive === 'dep') {
      if (words.length < 3) {
        throw new CliError(`line ${lineNumber}: expected dep <name> <dependency>...`, 2)
      }
      const [, name, ...depNames] = words
      if (!NAME_RE.test(name)) {
        throw new CliError(`line ${lineNumber}: invalid task name ${name}`, 2)
      }
      for (const depName of depNames) {
        if (!NAME_RE.test(depName)) {
          throw new CliError(`line ${lineNumber}: invalid task name ${depName}`, 2)
        }
      }
      pendingDeps.push({ name, depNames })
      usageOrder.push(name, ...depNames)
    } else {
      throw new CliError(`line ${lineNumber}: unknown directive ${directive}`, 2)
    }
  }

  for (const name of usageOrder) {
    if (!tasks.has(name)) {
      throw new CliError(`unknown task ${name}`, 2)
    }
  }

  for (const { name, depNames } of pendingDeps) {
    const task = tasks.get(name)
    for (const depName of depNames) {
      task.deps.add(depName)
    }
  }

  return tasks
}
"}

