{"file_path":"src/graph.js","content":"import { CliError } from './errors.js'

/**
 * Finds the first cycle a depth-first search discovers when it visits tasks
 * in ascending name order and walks each task's dependencies in ascending
 * name order. Returns the cycle as an array of names starting and ending
 * with the re-entered task, or null when the graph is acyclic.
 */
export function findCycle(tasks) {
  const names = [...tasks.keys()].sort()
  const visited = new Set()
  const stack = []
  const onStack = new Set()

  function visit(name) {
    stack.push(name)
    onStack.add(name)
    const deps = [...tasks.get(name).deps].sort()
    for (const dep of deps) {
      if (onStack.has(dep)) {
        const idx = stack.indexOf(dep)
        return stack.slice(idx).concat([dep])
      }
      if (!visited.has(dep)) {
        const found = visit(dep)
        if (found) return found
      }
    }
    stack.pop()
    onStack.delete(name)
    visited.add(name)
    return null
  }

  for (const name of names) {
    if (!visited.has(name)) {
      const found = visit(name)
      if (found) return found
    }
  }
  return null
}

/**
 * Raises a CliError describing the cycle as
 * `error: cycle: a -> b -> a`, wired to exit code 3.
 */
export function cycleError(cycle) {
  return new CliError(`cycle: ${cycle.join(' -> ')}`, 3)
}

/**
 * Computes, for every task, its start, finish and depth (wave), assuming
 * the graph is acyclic. Start is the greatest finish among its
 * dependencies, or 0 when it has none; finish is start plus cost; depth is
 * 1 + the greatest depth among its dependencies, or 0 when it has none.
 */
export function computeTimings(tasks) {
  const depthMemo = new Map()
  const finishMemo = new Map()

  function depthOf(name) {
    if (depthMemo.has(name)) return depthMemo.get(name)
    let depth = 0
    for (const dep of tasks.get(name).deps) {
      depth = Math.max(depth, depthOf(dep) + 1)
    }
    depthMemo.set(name, depth)
    return depth
  }

  function finishOf(name) {
    if (finishMemo.has(name)) return finishMemo.get(name)
    let start = 0
    for (const dep of tasks.get(name).deps) {
      start = Math.max(start, finishOf(dep))
    }
    const finish = start + tasks.get(name).cost
    finishMemo.set(name, finish)
    return finish
  }

  const result = new Map()
  for (const name of tasks.keys()) {
    const finish = finishOf(name)
    const start = finish - tasks.get(name).cost
    result.set(name, { start, finish, depth: depthOf(name) })
  }
  return result
}
"}

