{"file_path":"src/pack.js","content":"/**
 * Computes, for every task, the priority `pack` schedules by: the cost of
 * the longest chain of tasks that begins at it and follows dependents down
 * to a task nothing depends on.
 */
function computePriorities(tasks) {
  const dependents = new Map()
  for (const name of tasks.keys()) dependents.set(name, [])
  for (const [name, task] of tasks) {
    for (const dep of task.deps) dependents.get(dep).push(name)
  }

  const memo = new Map()
  function priorityOf(name) {
    if (memo.has(name)) return memo.get(name)
    let best = 0
    for (const successor of dependents.get(name)) {
      best = Math.max(best, priorityOf(successor))
    }
    const priority = tasks.get(name).cost + best
    memo.set(name, priority)
    return priority
  }

  for (const name of tasks.keys()) priorityOf(name)
  return memo
}

/**
 * Simulates the build graph on `workerCount` workers, following the
 * greedy priority rule described in the task prompt. Returns
 * `{ workers, makespan }`, where `workers` is an array (one entry per
 * worker) of `{ name, start, finish }` runs in the order they ran.
 */
export function packSchedule(tasks, workerCount) {
  const priorities = computePriorities(tasks)
  const names = [...tasks.keys()]
  const total = names.length

  const nextFree = new Array(workerCount).fill(0)
  const runs = Array.from({ length: workerCount }, () => [])
  const finishOf = new Map()
  const started = new Set()
  let doneCount = 0
  let currentTime = 0
  let makespan = 0

  const pending = new Set(names)

  function isReady(name) {
    for (const dep of tasks.get(name).deps) {
      const finish = finishOf.get(dep)
      if (finish === undefined || finish > currentTime) return false
    }
    return true
  }

  while (doneCount < total) {
    let progressed = true
    while (progressed) {
      progressed = false
      let freeWorker = -1
      for (let i = 0; i < workerCount; i++) {
        if (nextFree[i] <= currentTime) {
          freeWorker = i
          break
        }
      }
      if (freeWorker === -1) break

      let chosen = null
      for (const name of pending) {
        if (!isReady(name)) continue
        if (
          chosen === null ||
          priorities.get(name) > priorities.get(chosen) ||
          (priorities.get(name) === priorities.get(chosen) && name < chosen)
        ) {
          chosen = name
        }
      }
