{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js waves`, `node src/cli.js explain` and
 * `node src/cli.js pack <workers>` each report on the build graph read from
 * standard input.
 */

import { readFileSync } from 'node:fs'
import { CliError } from './errors.js'
import { parseGraph } from './parse.js'
import { findCycle, cycleError, computeTimings } from './graph.js'
import { packSchedule } from './pack.js'

const USAGE = 'usage: cli.js waves|explain|pack <workers>'
const WORKERS_RE = /^(?:[1-9][0-9]*)$/

function readArgs(argv) {
  if (argv.length === 1 && (argv[0] === 'waves' || argv[0] === 'explain')) {
    return { mode: argv[0] }
  }
  if (argv.length === 2 && argv[0] === 'pack') {
    if (!WORKERS_RE.test(argv[1])) {
      throw new CliError('workers must be a positive integer', 2)
    }
    return { mode: 'pack', workers: parseInt(argv[1], 10) }
  }
  throw new CliError(USAGE, 2)
}

function readStdin() {
  try {
    return readFileSync(0, 'utf8')
  } catch {
    return ''
  }
}

function renderWaves(tasks, timings) {
  const byDepth = new Map()
  let maxDepth = -1
  for (const [name, { depth }] of timings) {
    if (!byDepth.has(depth)) byDepth.set(depth, [])
    byDepth.get(depth).push(name)
    if (depth > maxDepth) maxDepth = depth
  }

  const lines = []
  for (let depth = 0; depth <= maxDepth; depth++) {
    const names = (byDepth.get(depth) ?? []).sort()
    lines.push(`wave ${depth}: ${names.join(' ')}`)
  }

  let total = 0
  for (const { finish } of timings.values()) total = Math.max(total, finish)
  lines.push(`total ${total}`)
  return lines.join('\n') + '\n'
}

function renderExplain(tasks, timings) {
  const lines = []
  for (const name of [...tasks.keys()].sort()) {
    const { start, finish, depth } = timings.get(name)
    lines.push(`${name} start=${start} finish=${finish} depth=${depth}`)
  }

  let total = 0
  for (const { finish } of timings.values()) total = Math.max(total, finish)
  lines.push(`total ${total}`)
  return lines.join('\n') + '\n'
}

function renderPack(tasks, workerCount) {
  const { workers, makespan } = packSchedule(tasks, workerCount)
  const lines = workers.map((runs, i) => {
    const parts = runs.map(({ name, start, finish }) => `${name}@${start}-${finish}`)
    return parts.length > 0 ? `worker ${i}: ${parts.join(' ')}` : `worker ${i}:`
  })
  lines.push(`makespan ${makespan}`)
  return lines.join('\n') + '\n'
}

function main() {
  const { mode, workers } = readArgs(process.argv.slice(2))
  const input = readStdin()
  const tasks = parseGraph(input)

  const cycle = findCycle(tasks)
  if (cycle) throw cycleError(cycle)

  const timings = computeTimings(tasks)

  if (mode === 'waves') {
    process.stdout.write(renderWaves(tasks, timings))
  } else if (mode === 'explain') {
    process.stdout.write(renderExplain(tasks, timings))
  } else {
    process.stdout.write(renderPack(tasks, workers))
  }
}

try {
  main()
} catch (err) {
  if (err instanceof CliError) {
    process.stderr.write(`error: ${err.message}\n`)
    process.exit(err.exitCode)
  }
  throw err
}
"}

